import type Device from '../lib/Device';
export type SpeechChunk = {
    transcript: string;
    startWord: number;
    endWord: number;
    type: string;
};
export type SpeechLocation = {
    transcript: string;
    startWord: number;
    endWord: number;
};
export type SpeechTimeValue = {
    second: number | false;
    minute: number | false;
    hour: number | false;
    fuzzyHour: boolean;
    day: number | false;
    month: number | false;
    year: number | false;
};
export type SpeechTime = {
    transcript: string;
    startWord: number;
    endWord: number;
    time: SpeechTimeValue;
};
export type SpeechWord = {
    word: string;
    posTag: string;
    chunks: SpeechChunk[];
    locations: SpeechLocation[];
    times: SpeechTime[];
    devices: unknown;
};
export type SpeechResult = {
    session: string;
    transcript: string;
    matches: Record<string, unknown>;
    words: SpeechWord[];
    chunks: SpeechChunk[];
    locations: SpeechLocation[];
    times: SpeechTime[];
    devices: Device[];
    allZones: string;
};
export type MatchedSpeechResult = SpeechResult & {
    say: (text: string, opts?: Record<string, unknown>) => Promise<unknown>;
    ask: (text: string, opts?: Record<string, unknown>) => Promise<string>;
    confirm: (text: string, opts?: Record<string, unknown>) => Promise<boolean>;
};
export type OnSpeechEvalEvent = {
    args: SpeechResult;
    return: boolean;
};
export type OnSpeechMatchEvent = {
    args: {
        speech: SpeechResult;
        onSpeechData: unknown;
    };
    return: void;
};
export type AskEvent = {
    args: {
        text: string;
        opts?: {
            session?: string;
            timeout?: number;
        };
    };
    return: string;
};
export type ConfirmEvent = {
    args: {
        text: string;
        opts?: {
            session?: string;
            timeout?: number;
        };
    };
    return: boolean;
};
export type HomeySpeechInputEvents = {
    onSpeechEval: OnSpeechEvalEvent;
    onSpeechMatch: OnSpeechMatchEvent;
};
export type SDKSpeechInputEvents = {
    ask: AskEvent;
    confirm: ConfirmEvent;
};
